-- SYNTHETIC LOCAL DATABASE ONLY. Never execute in a Supabase project.
do $$begin if current_database()<>'aimade_moderation_qa' then raise exception 'Local synthetic fixture only';end if;end$$;
create role anon;
create role authenticated;
create schema auth;
create schema aimade_internal;
grant usage on schema public,auth,aimade_internal to anon,authenticated;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table public.admins(user_id uuid primary key);
create table public.works(id uuid primary key default gen_random_uuid(),created_at timestamptz default now(),owner uuid not null,owner_name text not null default 'Anonymous',title text not null check(char_length(title) between 1 and 120),category text not null,description text check(char_length(description)<=2000),link text,cover_url text,price numeric default 0,accept_tips boolean default true,details jsonb not null default '{}',archived boolean not null default false);
create table public.likes(work_id uuid references works(id) on delete cascade,user_id uuid);
create table public.reports(work_id uuid references works(id) on delete cascade,reporter uuid,reason text);
alter table works enable row level security;
alter table admins enable row level security;
create policy "read own admin row" on admins for select using(auth.uid()=user_id);
create policy "public read works" on works for select using(not archived or auth.uid()=owner or exists(select 1 from admins where user_id=auth.uid()));
create policy "owner insert works" on works for insert with check(auth.uid()=owner);
create policy "owner update works" on works for update using(auth.uid()=owner) with check(auth.uid()=owner);
create policy "owner delete works" on works for delete using(auth.uid()=owner);
create policy "admin update any work" on works for update using(exists(select 1 from admins where user_id=auth.uid()));
create policy "admin delete any work" on works for delete using(exists(select 1 from admins where user_id=auth.uid()));
grant select on works,likes,admins to anon,authenticated;
grant insert,update,delete on works to authenticated;
create function public.guard_work_identity_v2() returns trigger language plpgsql set search_path='' as $$begin if tg_op='INSERT' then new.created_at=now(); elsif new.id is distinct from old.id or new.owner is distinct from old.owner or new.created_at is distinct from old.created_at then raise exception 'Work identity and creation time are immutable'; end if; return new; end;$$;
create trigger a_guard_work_identity_v2 before insert or update on works for each row execute function guard_work_identity_v2();
insert into admins values('00000000-0000-4000-8000-000000000001');
insert into works(id,owner,owner_name,title,category,description,archived) values('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000002','Synthetic owner','1','prompt','Short legacy description',true);
create view work_catalog with(security_invoker=true) as select w.*,(select count(*)::integer from likes l where l.work_id=w.id) as likes_count from works w;
grant select on work_catalog to anon,authenticated;
